<?php

namespace MongoDB\Driver\Monitoring;

/**
 * <div id="class.mongodb-driver-monitoring-logsubscriber" class="reference"> <h1 class="title">The MongoDB\Driver\Monitoring\LogSubscriber interface</h1>  <div class="partintro"><p class="verinfo">(mongodb &gt;=1.17.0)</p>  <div class="section" id="mongodb-driver-monitoring-logsubscriber.intro">   <h2 class="title">简介</h2>   <p class="simpara">    Classes implementing this interface may be registered as a subscriber and    receive log messages from the extension. This is similar to stream-based    debug logging (i.e. <a href="https://php.net/manual/zh/mongodb.configuration.php#ini.mongodb.debug" class="link">mongodb.debug</a>)    except that trace-level log messages are <em>not</em> received.   </p>   <p class="simpara">    As with stream-based logging, it is only possible to register a logger    globally using <span class="function">{@link MongoDB\Driver\Monitoring\addSubscriber()}</span>.    The extension is not able to distinguish log messages for individual    <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-manager.php" class="classname">MongoDB\Driver\Manager</a></span> objects.   </p>  </div>  <div class="section" id="mongodb-driver-monitoring-logsubscriber.synopsis">   <h2 class="title">接口摘要</h2>   <div class="classsynopsis">    <span class="ooclass"><strong class="classname"></strong></span>    <div class="classsynopsisinfo">     <span class="ooclass">      <span class="modifier">class</span> <strong class="classname">MongoDB\Driver\Monitoring\LogSubscriber</strong>     </span>     <span class="oointerface"><span class="modifier">implements</span>        <a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-subscriber.php" class="interfacename">MongoDB\Driver\Monitoring\Subscriber</a></span> {</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 常量 </div>    <div class="fieldsynopsis">     <span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-logsubscriber.php#mongodb-driver-monitoring-logsubscriber.constants.level-error"><var class="varname">LEVEL_ERROR</var></a></var><span class="initializer"> = 0</span>;</div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-logsubscriber.php#mongodb-driver-monitoring-logsubscriber.constants.level-critical"><var class="varname">LEVEL_CRITICAL</var></a></var><span class="initializer"> = 1</span>;</div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-logsubscriber.php#mongodb-driver-monitoring-logsubscriber.constants.level-warning"><var class="varname">LEVEL_WARNING</var></a></var><span class="initializer"> = 2</span>;</div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-logsubscriber.php#mongodb-driver-monitoring-logsubscriber.constants.level-message"><var class="varname">LEVEL_MESSAGE</var></a></var><span class="initializer"> = 3</span>;</div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-logsubscriber.php#mongodb-driver-monitoring-logsubscriber.constants.level-info"><var class="varname">LEVEL_INFO</var></a></var><span class="initializer"> = 4</span>;</div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-logsubscriber.php#mongodb-driver-monitoring-logsubscriber.constants.level-debug"><var class="varname">LEVEL_DEBUG</var></a></var><span class="initializer"> = 5</span>;</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 方法 </div>    <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-monitoring-logsubscriber.log.php" class="methodname" style="color:#CC7832">log</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$level</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$domain</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$message</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>   }</div>  </div>  <div class="section" id="mongodb-driver-monitoring-logsubscriber.constants">   <h2 class="title">预定义常量</h2>   <dl>         <dt id="mongodb-driver-monitoring-logsubscriber.constants.level-error"><strong><span>{@link MongoDB\Driver\Monitoring\LogSubscriber::LEVEL_ERROR}</span></strong></dt>     <dd>      <span class="simpara">       Error log level. An error condition that the extension is unable to report       through its API. This is the most severe log level in the extension.      </span>     </dd>             <dt id="mongodb-driver-monitoring-logsubscriber.constants.level-critical"><strong><span>{@link MongoDB\Driver\Monitoring\LogSubscriber::LEVEL_CRITICAL}</span></strong></dt>     <dd>      <span class="simpara">       Critical log level. An error condition with slightly less severity. This       constant exists for consistency with libmongoc; however, the extension is       unlikely to use it in practice.      </span>     </dd>             <dt id="mongodb-driver-monitoring-logsubscriber.constants.level-warning"><strong><span>{@link MongoDB\Driver\Monitoring\LogSubscriber::LEVEL_WARNING}</span></strong></dt>     <dd>      <span class="simpara">       Warning log level. Indicates a situation where undesirable application       behavior may occur.      </span>     </dd>             <dt id="mongodb-driver-monitoring-logsubscriber.constants.level-message"><strong><span>{@link MongoDB\Driver\Monitoring\LogSubscriber::LEVEL_MESSAGE}</span></strong></dt>     <dd>      <span class="simpara">       Message or notice log level. Indicates an event that is unusual but not       problematic.      </span>     </dd>             <dt id="mongodb-driver-monitoring-logsubscriber.constants.level-info"><strong><span>{@link MongoDB\Driver\Monitoring\LogSubscriber::LEVEL_INFO}</span></strong></dt>     <dd>      <span class="simpara">       Info log level. High-level information about normal driver behavior.      </span>     </dd>             <dt id="mongodb-driver-monitoring-logsubscriber.constants.level-debug"><strong><span>{@link MongoDB\Driver\Monitoring\LogSubscriber::LEVEL_DEBUG}</span></strong></dt>     <dd>      <span class="simpara">       Debug log level. Detailed information that may be helpful when debugging       an application.      </span>     </dd>       </dl>  </div> </div>   <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link MongoDB\Driver\Monitoring\LogSubscriber::log} — Notification method for a log message</li></ul></div>
 * 
 * @since 1.17.0
 * @link https://www.php.net/manual/en/class.mongodb-driver-monitoring-logsubscriber.php
 */
interface LogSubscriber extends Subscriber
{
    public const LEVEL_ERROR = 0;
    public const LEVEL_CRITICAL = 1;
    public const LEVEL_WARNING = 2;
    public const LEVEL_MESSAGE = 3;
    public const LEVEL_INFO = 4;
    public const LEVEL_DEBUG = 5;

    /* MONGOC_LOG_LEVEL_TRACE is intentionally omitted. Trace logs are only
     * reported via streams (i.e. mongodb.debug INI), so the constant is not
     * relevant to LogSubscriber implementations. */

/**
 * <div id="mongodb-driver-monitoring-logsubscriber.log" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\Monitoring\LogSubscriber::log</h1>  <p class="verinfo">(mongodb &gt;=1.17.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\Monitoring\LogSubscriber::log</span> — <span class="dc-title">Notification method for a log message</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-monitoring-logsubscriber.log-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\Monitoring\LogSubscriber::log</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$level</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$domain</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$message</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="simpara">   If the subscriber is registered, this method is called for each logged   message.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-monitoring-logsubscriber.log-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">level</span></dt>    <dd>     <span class="simpara">      The severity level. This will be one of the      <a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-logsubscriber.php#mongodb-driver-monitoring-logsubscriber.constants" class="link">interface constants</a>.     </span>    </dd>          <dt><span class="parameter" style="color:#3A95FF">domain</span></dt>    <dd>     <span class="simpara">      The name of the driver component that emitted the log message.     </span>    </dd>          <dt><span class="parameter" style="color:#3A95FF">message</span></dt>    <dd>     <span class="simpara">      The log message.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-monitoring-logsubscriber.log-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   没有返回值。  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-monitoring-logsubscriber.log-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-monitoring-logsubscriber.log-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="function">{@link MongoDB\Driver\Monitoring\addSubscriber()} - Registers a monitoring event subscriber globally</span></li>  </ul> </div></div>
 */
    public function log(int $level, string $domain, string $message): void;
}
